def compute_stats(numbers):
    """Return mean / max / min of numbers (0/None/None for empty)."""
    total = 0
    count = 0
    for n in numbers:
        total += n
        count += 1
    if not numbers:
        return {"mean": 0, "max": None, "min": None}
    biggest = numbers[0]
    smallest = numbers[0]
    for n in numbers[1:]:
        if n > biggest:
            biggest = n
        if n < smallest:
            smallest = n
    return {"mean": total / count, "max": biggest, "min": smallest}

