def order_total(items, country):
    """Compute the final order total with country-specific discount + tax."""
    subtotal = 0
    for item in items:
        subtotal += item["price"] * item["qty"]
    if country == "US":
        if subtotal > 100:
            subtotal = subtotal * 0.9
        tax = subtotal * 0.08
    elif country == "EU":
        tax = subtotal * 0.2
    elif country == "IN":
        if subtotal > 50:
            subtotal = subtotal * 0.95
        tax = subtotal * 0.18
    else:
        tax = 0
    return round(subtotal + tax, 2)

